<?php require 'includes/conexao.php'; require 'includes/verificar_login.php'; exigir_login(); $stmt=$pdo->prepare('SELECT jogo, dificuldade,pontuacao,acertos,erros,jogado_em FROM resultados WHERE usuario_id=? ORDER BY jogado_em DESC'); $stmt->execute([$_SESSION['usuario_id']]); $historico=$stmt->fetchAll(); $titulo='Meu progresso'; $home='dashboard.php'; include 'includes/header.php'; ?><div class="section-heading"><div><div class="eyebrow">Tudo que você já construiu</div><h1 style="font-size:4rem">Meu progresso</h1><p>Seu histórico de missões fica guardado aqui.</p></div></div><div class="card"><table><thead><tr><th>Jogo</th><th>Nível</th><th>Acertos</th><th>Erros</th><th>Pontos</th><th>Data</th></tr></thead><tbody><?php foreach($historico as $item): ?><tr><td><?= htmlspecialchars($item['jogo']) ?></td><td><?= ucfirst($item['dificuldade']) ?></td><td style="color:var(--green)"><?= $item['acertos'] ?></td><td style="color:var(--coral)"><?= $item['erros'] ?></td><td><strong><?= $item['pontuacao'] ?></strong></td><td><?= date('d/m/Y H:i',strtotime($item['jogado_em'])) ?></td></tr><?php endforeach; if (!$historico): ?><tr><td colspan="6">Você ainda não completou uma missão.</td></tr><?php endif; ?></tbody></table></div><?php include 'includes/footer.php'; ?>
